/* N87: static RELs for the browser build. Every REL is one prelinked object whose symbols are local but its
 * ObjectSetup_<rel>, and whose .data/.bss are one wasm data segment pbrel_<rel> (tools/web_rel_localize.py).
 * web_rel_table.c (generated by CMake) lists them. A REL's data is kept as it was at boot and copied back on
 * its first link after an unlink, which is what dlopen after dlclose gives the desktop build. */
#include "port/web_rel.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct WebRel {
    const char *name;
    void (*setup)(void);
    char *start;
    char *stop;
} WebRel;

extern const WebRel web_rel_table[];
extern const int web_rel_count;

static unsigned char **images;
static int *links;

__attribute__((constructor)) static void web_rel_snapshot(void)
{
    int i;
    images = calloc(web_rel_count, sizeof(*images));
    links = calloc(web_rel_count, sizeof(*links));
    size_t total = 0;
    const int verbose = getenv("PB_WEB_REL_LOG") != NULL;
    for (i = 0; i < web_rel_count; i++) {
        const WebRel *rel = &web_rel_table[i];
        size_t size = rel->start ? (size_t)(rel->stop - rel->start) : 0;
        if (size) {
            images[i] = malloc(size);
            memcpy(images[i], rel->start, size);
        }
        if (verbose) {
            printf("web_rel: %s %p-%p (%zu bytes)\n", rel->name, (void *)rel->start, (void *)rel->stop, size);
        }
        total += size;
    }
    printf("web_rel: %d RELs, %zu bytes of data kept for relinking\n", web_rel_count, total);
}

void *web_rel_link(const char *name)
{
    int i;
    size_t len = strcspn(name, ".");
    for (i = 0; i < web_rel_count; i++) {
        const WebRel *rel = &web_rel_table[i];
        if (strncmp(rel->name, name, len) != 0 || rel->name[len] != '\0') {
            continue;
        }
        if (links[i]++ == 0 && images[i]) {
            memcpy(rel->start, images[i], (size_t)(rel->stop - rel->start));
        }
        return (void *)rel;
    }
    return NULL;
}

void web_rel_object_setup(void *rel)
{
    ((const WebRel *)rel)->setup();
}

void web_rel_unlink(void *rel)
{
    int i = (int)((const WebRel *)rel - web_rel_table);
    if (rel && links[i] > 0) {
        links[i]--;
    }
}
